#include <cstdio>
#include <vector>
#include <unordered_map>
#include <algorithm>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    std::unordered_map<long long, int> cnt;
    for (int i = 0; i < n; ++i) {
        long long x; scanf("%lld", &x);
        ++cnt[x];
    }

    std::vector<std::pair<long long,int>> v(cnt.begin(), cnt.end());
    std::sort(v.begin(), v.end(), [](const auto &a, const auto &b) {
        if (a.second != b.second) return a.second > b.second;  // 频次降序
        return a.first < b.first;                              // 值升序
    });

    for (int i = 0; i < k; ++i) {
        if (i) printf(" ");
        printf("%lld", v[i].first);
    }
    printf("\n");
    return 0;
}
